/*
 * MilestoneService: tiered guild achievements (the owner, 2026-11-12: [quote left out]; the design log
 * section 2.2, docs/guild-management.md "Tiered guild achievements").
 *
 * A series counts one thing for the whole guild and has tiers (ga_milestone_template, world database, generated by
 * tools/gen_milestones.py):
 *   level_class / level_race   the highest level a guild character of that class / race reached (10 .. 60; 70 and 80
 *                              wait for the level cap)
 *   skill                      the highest skill a guild character has in that profession (75 .. 300; 375 and 450
 *                              wait for the level cap)
 *   storage_items              items in the guild storage now (100 .. 1,000,000)
 *   guild_gold                 the guild's gold now, in gold: the WoW guild bank plus what the leader and every roster
 *                              bot carry (100 .. 1,000,000)
 *   kills                      creatures of that type the guild's characters killed (100 .. 1,000,000)
 *   quests                     quests the guild's characters completed, the same quest once per character (10 .. 100,000)
 *   dungeons / raids           dungeon and raid runs: the last boss of an instance (instance_encounters'
 *                              lastEncounterDungeon) killed by a guild character, once per instance and dungeon;
 *                              later dungeon orders can report runs with AddRun.
 * A tier is reached once per guild (ga_guild_milestone) and gives its points as guild points (perks, PerkService) and
 * points times GuildAdventure.Achievements.RenownPerPoint renown; the highest active tier of a series gives
 * GuildAdventure.Milestones.LastTierFactor times its points. A tier whose requires_level is above the server's
 * MaxPlayerLevel is inactive: it is shown but cannot be reached.
 *
 * Counting: kills, quests and runs come from player hooks (map threads), which only queue (QueueKill, QueueQuest,
 * QueueRun); Update drains the queue on the world thread. Levels, skills, storage items and gold are read by a scan of
 * the guild characters in the world every GuildAdventure.Milestones.ScanSeconds. Sums and maxima are kept in
 * ga_guild_counter, written at every scan and at shutdown. At startup the levels, skills and money of every guild
 * character come from the characters database, and a guild without a quest count yet starts with the quests its
 * characters completed before (character_queststatus_rewarded), so a guild gets the tiers it had already reached.
 *
 * World thread only, except the Queue* functions.
 */

#ifndef MOD_GUILD_ADVENTURE_MILESTONE_SERVICE_H
#define MOD_GUILD_ADVENTURE_MILESTONE_SERVICE_H

#include "Define.h"
#include "ObjectGuid.h"
#include <map>
#include <set>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>

class Player;

namespace GuildAdventure
{
    struct AdventureGuild;

    enum class MilestoneKind : uint8
    {
        LevelClass,
        LevelRace,
        Skill,
        StorageItems,
        GuildGold,
        Kills,
        Quests,
        Dungeons,
        Raids
    };

    char const* ToToken(MilestoneKind kind);

    struct MilestoneTier
    {
        uint32 id = 0;
        uint8 tier = 0;
        uint64 threshold = 0;
        uint32 points = 0;        // base points; the last active tier gets LastTierFactor times this
        uint8 requiresLevel = 0;  // active only while MaxPlayerLevel >= this
    };

    struct MilestoneSeries
    {
        MilestoneKind kind = MilestoneKind::Quests;
        uint32 subject = 0;       // class, race, skill line, creature type; 0 for guild-wide series
        std::string key;          // counter key: "kills_7", "quests", "level_class_1" (ga_guild_counter)
        std::string name;         // "Warrior", "Mining", "Beasts", "" (ga_milestone_template.comment)
        std::vector<MilestoneTier> tiers; // by tier, ascending

        bool IsSum() const;       // kills, quests, runs: counted up; else a maximum or a live value
        bool IsLive() const;      // storage items and gold: read now, not kept
    };

    struct EarnedMilestone
    {
        ObjectGuid earnedBy;
        uint32 earnedAt = 0;
        uint32 points = 0;
        int32 renown = 0;
    };
}

class MilestoneService
{
public:
    static MilestoneService& Instance();

    // Startup (world thread, after the guilds are loaded): templates, then the guilds' tiers and counters.
    void Load();
    // World thread, every tick: drains the hook queue, scans, writes counters, pushes the MILESTONES block.
    void Update(uint32 diff);
    // Shutdown: writes the counters that changed since the last scan (synchronously).
    void Flush();

    // Hooks, any thread.
    static void QueueKill(ObjectGuid credited, uint32 creatureType);
    static void QueueQuest(ObjectGuid character);
    // A dungeon or raid run ended with its last boss (instanceId + the LFG dungeon id keep a run from counting twice).
    static void QueueRun(ObjectGuid character, bool raid, uint32 instanceId, uint32 dungeonId);
    // The creature types that count as kills.
    static bool CountsAsKill(uint32 creatureType);

    // For later dungeon and raid orders (world thread): the guild finished a run.
    void AddRun(GuildAdventure::AdventureGuild& guild, bool raid, ObjectGuid by);
    // Tests and GM: adds to a sum or raises a maximum, then awards what it reaches. False for an unknown or live key.
    bool AddToCounter(GuildAdventure::AdventureGuild& guild, std::string const& key, uint64 amount, ObjectGuid by);
    // Reads the guild's characters in the world now and awards what they reached (GM; the scan does it by itself).
    void ScanGuild(GuildAdventure::AdventureGuild& guild);

    // --- queries (world thread) ---
    std::vector<GuildAdventure::MilestoneSeries> const& GetSeries() const { return _series; }
    GuildAdventure::MilestoneSeries const* FindSeries(std::string const& key) const;
    uint64 GetValue(GuildAdventure::AdventureGuild const& guild, GuildAdventure::MilestoneSeries const& series) const;
    bool HasEarned(GuildAdventure::AdventureGuild const& guild, uint32 milestoneId) const;
    // How many tiers of the series are active (the level cap allows them).
    uint8 GetActiveTiers(GuildAdventure::MilestoneSeries const& series) const;
    // The points a tier gives (its index in series.tiers): the last active one LastTierFactor times its base.
    uint32 GetTierPoints(GuildAdventure::MilestoneSeries const& series, std::size_t index) const;
    std::string DescribeTier(GuildAdventure::MilestoneSeries const& series, GuildAdventure::MilestoneTier const& tier) const;

    uint32 GetEarnedCount(GuildAdventure::AdventureGuild const& guild) const;
    uint32 GetActiveCount() const;                                         // active tiers of every series
    uint32 GetPoints(GuildAdventure::AdventureGuild const& guild) const;   // guild points the tiers gave
    int32 GetRenown(GuildAdventure::AdventureGuild const& guild) const;    // renown the tiers gave

private:
    MilestoneService() = default;

    struct GuildState
    {
        std::map<uint32, GuildAdventure::EarnedMilestone> earned;  // by milestone id
        std::unordered_map<std::string, uint64> counters;          // sums and maxima (ga_guild_counter)
        std::set<std::string> dirty;                               // counters to write
        std::unordered_map<std::string, ObjectGuid> holders;       // who raised a maximum last
        std::set<std::pair<uint32, uint32>> runs;                  // (instance id, dungeon id) counted since startup
        std::unordered_map<ObjectGuid, uint64> money;              // copper per guild character, last known
        uint64 goldValue = 0;                                       // the guild's gold, in gold
        bool loaded = false;                                        // LoadGuild ran (members from the database)
    };

    struct Award
    {
        GuildAdventure::MilestoneSeries const* series = nullptr;
        GuildAdventure::MilestoneTier const* tier = nullptr;
        ObjectGuid by;
        uint32 points = 0;
    };

    void LoadTemplates();
    void LoadGuild(GuildAdventure::AdventureGuild const& guild, GuildState& state);
    GuildState& State(uint32 ownerAccount);
    GuildState const* FindState(uint32 ownerAccount) const;

    void ProcessQueue();
    void ScanAll();
    void ScanMembers(GuildAdventure::AdventureGuild const& guild, GuildState& state);
    void RaiseMax(GuildState& state, std::string const& key, uint64 value, ObjectGuid holder);
    void AddSum(GuildState& state, std::string const& key, uint64 amount);
    void WriteCounters(uint32 ownerAccount, GuildState& state, bool direct);

    // Awards every tier of the series the guild's value reaches and has not got; appends to 'awards'.
    void Evaluate(GuildAdventure::AdventureGuild const& guild, GuildState& state, GuildAdventure::MilestoneSeries const& series,
        ObjectGuid by, std::vector<Award>& awards);
    void EvaluateAll(GuildAdventure::AdventureGuild const& guild, GuildState& state, std::vector<Award>& awards);
    // Renown, events, pushes for what one pass awarded.
    void Announce(GuildAdventure::AdventureGuild& guild, std::vector<Award> const& awards);

    std::vector<GuildAdventure::MilestoneSeries> _series;
    std::unordered_map<std::string, std::size_t> _seriesByKey;
    std::unordered_map<uint32, GuildState> _guilds;
    uint32 _scanTimer = 0;
    bool _loaded = false;
};

#define sMilestoneService MilestoneService::Instance()

#endif
